fn find_median(a: &[i32], b: &[i32]) -> i32 {
    let n = a.len();
    // preconditions: both slices have the same positive length
    assert!(n > 0, "arrays must be non‐empty");
    assert_eq!(n, b.len(), "arrays must have the same length");

    if n % 2 == 1 {
        // odd length: return the middle element of `a`
        a[n / 2]
    } else {
        // even length: average of
        //   - the last element of the lower half of `a` (index n/2 - 1)
        //   - the first element of `b` (index 0)
        //
        // We compute ⌊(x + y) / 2⌋ even for negative sums.
        let x = a[n / 2 - 1] as i64;
        let y = b[0] as i64;
        let sum = x + y;
        let avg = if sum >= 0 {
            sum / 2
        } else {
            // floor division for negative sums
            (sum - 1) / 2
        };
        avg as i32
    }
}

